type Shape = number[];
type ConvCase = {
  name: string;
  cls: "Conv1d" | "Conv2d" | "Conv3d";
  args: [number, number, number | number[]];
  opts: Record<string, unknown>;
  xshape: Shape;
  wshape: Shape;
  hasBias: boolean;
  yshape: Shape;
  y: number[];
  gx: number[];
  gw: number[];
};
type PoolCase = {
  name: string;
  cls: "MaxPool1d" | "MaxPool2d" | "MaxPool3d" | "AvgPool1d" | "AvgPool2d" | "AvgPool3d";
  args: [number | number[]];
  opts: Record<string, unknown>;
  xshape: Shape;
  yshape: Shape;
  y: number[];
  gx: number[];
};
type ActCase = {
  name: string;
  cls: string;
  args: unknown[];
  x: Array<number | string | null>;
  y: Array<number | string | null>;
  gx: Array<number | string | null>;
};
type MhaCase = {
  name: string;
  qshape: Shape;
  kshape: Shape;
  opts: {
    averageAttnWeights?: boolean;
    kpm?: "bool" | "float";
    attn?: "bool";
    unbatched?: boolean;
    valueIsKey?: boolean;
  };
  out: number[];
  w: number[];
  wshape: Shape;
};
type Keys = Array<[string, Shape]>;
type TransCase = {
  name: string;
  kind: "enc" | "dec";
  act: "relu" | "gelu";
  nf: boolean;
  out: number[];
  shape: Shape;
};
type Fixtures = {
  conv: ConvCase[];
  pool: PoolCase[];
  acts: ActCase[];
  mha: {
    keys: Keys;
    cases: MhaCase[];
    kpmBool: number[];
    kpmFloat: number[];
    attnBool: number[];
  };
  trans: { encKeys: Keys; decKeys: Keys; cases: TransCase[]; causal: number[] };
  train: { four_two: number[]; three_two: number[]; three_one: number[]; five_three: number[] };
  optim: Record<string, { a: number[]; b: number[] }>;
};

const FIX = JSON.parse(FIXTURES) as Fixtures;

// ---------------------------------------------------------------- helpers

/** Deterministic test signal, mirrored by the Python generator of the fixtures. */
function seq(n: number, amp: number, freq: number, phase: number): number[] {
  return Array.from({ length: n }, (_, i) => amp * Math.sin(freq * i + phase));
}

function prod(shape: readonly number[]): number {
  return shape.reduce((a, b) => a * b, 1);
}

function f64(data: number[], shape: Shape): Tensor {
  return tensor(data, { dtype: "float64" }).reshape(shape);
}

function raw(t: AnyTensor): Tensor {
  return GradTensor.isGradTensor(t) ? t.tensor : t;
}

/** Logical values of a tensor in row-major order. */
function values(t: AnyTensor | Tensor): number[] {
  const arr = raw(t).toArray() as unknown;
  return Array.isArray(arr) ? (arr.flat(Number.POSITIVE_INFINITY) as number[]) : [arr as number];
}

/** Fixture numbers: null is NaN, and infinities are stored as strings. */
function decode(v: number | string | null): number {
  if (v === null) return Number.NaN;
  if (v === "Infinity") return Number.POSITIVE_INFINITY;
  if (v === "-Infinity") return Number.NEGATIVE_INFINITY;
  return v as number;
}

function expectClose(actual: number[], expected: number[], tol = 1e-8): void {
  expect(actual.length).toBe(expected.length);
  for (let i = 0; i < expected.length; i++) {
    const a = actual[i] as number;
    const e = expected[i] as number;
    if (Number.isNaN(e)) {
      expect(a, `element ${i}`).toBeNaN();
    } else if (!Number.isFinite(e)) {
      expect(a, `element ${i}`).toBe(e);
    } else {
      expect(Math.abs(a - e), `element ${i}: ${a} vs ${e}`).toBeLessThanOrEqual(
        tol * Math.max(1, Math.abs(e))
      );
    }
  }
}

type StateParams = Record<string, { data: number[]; shape: Shape; dtype: "float64" }>;

/** Parameter values written by the fixture generator: `scale * sin(0.37 j + 1.7 k + 0.4)`. */
function paramState(keys: Keys, scale: number): { parameters: StateParams } {
  const parameters: StateParams = {};
  keys.forEach(([name, shape], k) => {
    parameters[name] = {
      data: seq(prod(shape), scale, 0.37, 1.7 * k + 0.4),
      shape,
      dtype: "float64",
    };
  });
  return { parameters };
}

/** Parameter of a module by its registered name. */
function paramOf(module: Module, name: string): GradTensor {
  const found = new Map(module.namedParameters()).get(name);
  if (!found) throw new Error(`no parameter ${name}`);
  return found;
}

function scalarOf(t: AnyTensor): number {
  return values(t)[0] as number;
}

// ---------------------------------------------------------------- activations

describe("new activation layers match PyTorch", () => {
  const classes = {
    ReLU6,
    LogSigmoid,
    CELU,
    Softshrink,
    Hardshrink,
    Threshold,
    GELU,
  } as unknown as Record<string, new (...args: unknown[]) => Module>;

  it.each(FIX.acts.map((c) => [c.name, c] as const))("%s: values and gradients", (_name, c) => {
    const layer = new classes[c.cls]!(...c.args);
    const x = c.x.map(decode);
    const plain = layer.forward(f64(x, [x.length]));
    expect(plain.dtype).toBe("float64");
    expectClose(values(plain), c.y.map(decode));

    const input = GradTensor.fromTensor(f64(x, [x.length]), { requiresGrad: true });
    const out = layer.forward(input) as GradTensor;
    expectClose(values(out), c.y.map(decode));
    out.backward(f64(new Array(x.length).fill(1), [x.length]));
    expectClose(values(input.grad as Tensor), c.gx.map(decode));
  });

  it("GELU keeps the tanh approximation as its default and accepts a string", () => {
    const x = f64([-1, 0.5, 2], [3]);
    const exact = values(new GELU({ approximate: "none" }).forward(x));
    const tanhForm = values(new GELU({ approximate: "tanh" }).forward(x));
    expectClose(values(new GELU().forward(x)), tanhForm, 1e-15);
    expectClose(values(new GELU("none").forward(x)), exact, 1e-15);
    // Reference values from torch.nn.functional.gelu
    expectClose(exact, [-0.15865525393145707, 0.34573123063700656, 1.9544997361036416], 1e-12);
    expectClose(tanhForm, [-0.15880800939172324, 0.34571400982514394, 1.954597694087775], 1e-12);
    expect(new GELU().toString()).toBe("GELU()");
    expect(new GELU({ approximate: "none" }).toString()).toBe('GELU(approximate="none")');
    expect(() => new GELU({ approximate: "erf" as "none" })).toThrow(InvalidParameterError);
    expect(() => new GELU("fast" as "none")).toThrow(InvalidParameterError);
  });

  it("keep the float dtype and give float32 for integer input (ReLU6 keeps integers)", () => {
    const layers: Module[] = [
      new ReLU6(),
      new LogSigmoid(),
      new CELU(),
      new Softshrink(),
      new Hardshrink(),
      new Threshold(0, 1),
    ];
    for (const layer of layers) {
      expect(layer.forward(tensor([-1, 2], { dtype: "float32" })).dtype).toBe("float32");
      expect(layer.forward(tensor([-1, 2], { dtype: "float64" })).dtype).toBe("float64");
      if (!(layer instanceof ReLU6)) {
        expect(layer.forward(tensor([-1, 2], { dtype: "int32" })).dtype).toBe("float32");
      }
    }
    // ReLU6 is a clamp, so integer input stays integer (like ReLU)
    expect(values(new ReLU6().forward(tensor([-1, 2, 9], { dtype: "int32" })))).toEqual([0, 2, 6]);
  });

  it("read non-contiguous views, 0-d and empty tensors", () => {
    const base = f64(seq(12, 3, 0.9, 0.2), [3, 4]);
    const view = base.transpose();
    const copy = f64(values(view), [4, 3]);
    const layers: Module[] = [
      new ReLU6(),
      new LogSigmoid(),
      new CELU(1.5),
      new Softshrink(0.7),
      new Hardshrink(0.7),
      new Threshold(0.2, -3),
      new GELU({ approximate: "none" }),
    ];
    for (const layer of layers) {
      expectClose(values(layer.forward(view)), values(layer.forward(copy)), 1e-15);
      expect(layer.forward(view).shape).toEqual([4, 3]);

      const scalar = layer.forward(f64([1.25], []).reshape([]));
      expect(scalar.shape).toEqual([]);
      expect(Number.isNaN(scalarOf(scalar))).toBe(false);

      const empty = layer.forward(f64([], [0, 3]));
      expect(empty.shape).toEqual([0, 3]);
      expect(empty.size).toBe(0);
    }
  });

  it("backpropagate through views and keep the input shape", () => {
    const base = GradTensor.fromTensor(f64(seq(6, 2, 1.1, 0.3), [2, 3]), { requiresGrad: true });
    const layers: Module[] = [new ReLU6(), new LogSigmoid(), new CELU(), new Softshrink(0.2)];
    for (const layer of layers) {
      base.zeroGrad();
      const out = layer.forward(base.transpose()) as GradTensor;
      expect(out.shape).toEqual([3, 2]);
      out.backward(f64(new Array(6).fill(1), [3, 2]));
      expect((base.grad as Tensor).shape).toEqual([2, 3]);
    }
  });

  it("validate their parameters", () => {
    expect(() => new CELU(0)).toThrow(InvalidParameterError);
    expect(() => new CELU(Number.NaN)).toThrow(InvalidParameterError);
    expect(() => new CELU(Number.POSITIVE_INFINITY)).toThrow(InvalidParameterError);
    expect(() => new Softshrink(-0.1)).toThrow(InvalidParameterError);
    expect(() => new Softshrink(Number.NaN)).toThrow(InvalidParameterError);
    expect(() => new Hardshrink(-1)).toThrow(InvalidParameterError);
    expect(() => new Threshold(Number.NaN, 0)).toThrow(InvalidParameterError);
    expect(() => new Threshold(0, Number.NaN)).toThrow(InvalidParameterError);
    expect(new Softshrink(0).forward(f64([-1, 0, 2], [3])).toArray()).toEqual([-1, 0, 2]);
  });

  it("have readable names", () => {
    expect(new ReLU6().toString()).toBe("ReLU6()");
    expect(new LogSigmoid().toString()).toBe("LogSigmoid()");
    expect(new CELU(2).toString()).toBe("CELU(alpha=2)");
    expect(new Softshrink().toString()).toBe("Softshrink(lambd=0.5)");
    expect(new Hardshrink(1).toString()).toBe("Hardshrink(lambd=1)");
    expect(new Threshold(0.1, 20).toString()).toBe("Threshold(threshold=0.1, value=20)");
  });

  it("work inside Sequential with a training step", () => {
    const model = new Sequential(
      new Linear(2, 3, { dtype: "float64" }),
      new ReLU6(),
      new Linear(3, 1, { dtype: "float64" })
    );
    const out = model.forward(f64([0.5, -1, 2, 0.25], [2, 2]));
    expect(out.shape).toEqual([2, 1]);
    const loss = mseLoss(out, f64([1, 0], [2, 1]));
    (loss as GradTensor).backward();
    for (const p of model.parameters()) expect(p.grad).not.toBeNull();
  });
});

// ---------------------------------------------------------------- convolution

describe("convolution dilation, groups and padding match PyTorch", () => {
  const classes = { Conv1d, Conv2d, Conv3d };

  it.each(FIX.conv.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const layer = new classes[c.cls](
      c.args[0],
      c.args[1],
      c.args[2] as never,
      {
        ...c.opts,
        dtype: "float64",
      } as never
    );
    const w = seq(prod(c.wshape), 0.6, 0.37, 0.5);
    const parameters: StateParams = { weight: { data: w, shape: c.wshape, dtype: "float64" } };
    if (c.hasBias) {
      const outC = c.wshape[0] as number;
      parameters["bias"] = { data: seq(outC, 0.1, 1.3, 0.2), shape: [outC], dtype: "float64" };
    }
    layer.loadStateDict({ parameters });
    expect(layer.weight.shape).toEqual(c.wshape);

    const x = GradTensor.fromTensor(f64(seq(prod(c.xshape), 0.9, 0.7, 0.3), c.xshape), {
      requiresGrad: true,
    });
    const y = layer.forward(x);
    expect(y.shape).toEqual(c.yshape);
    expectClose(values(y), c.y);

    y.backward(f64(seq(prod(c.yshape), 1.0, 0.53, 1.1), c.yshape));
    expectClose(values(x.grad as Tensor), c.gx);
    expectClose(values(layer.weight.grad as Tensor), c.gw);
  });

  it("same padding keeps the spatial size for every kernel, dilation and rank", () => {
    for (const k of [1, 2, 3, 4, 5]) {
      for (const d of [1, 2, 3]) {
        const conv1 = new Conv1d(1, 2, k, { padding: "same", dilation: d });
        expect(conv1.forward(zeros([2, 1, 7])).shape).toEqual([2, 2, 7]);
        const conv2 = new Conv2d(1, 1, k, { padding: "same", dilation: d });
        expect(conv2.forward(zeros([1, 1, 6, 5])).shape).toEqual([1, 1, 6, 5]);
      }
    }
    const conv3 = new Conv3d(1, 1, [2, 3, 4], { padding: "same" });
    expect(conv3.forward(zeros([1, 1, 3, 4, 5])).shape).toEqual([1, 1, 3, 4, 5]);
  });

  it("valid padding equals padding 0", () => {
    setSeed(5);
    const a = new Conv2d(2, 3, 3, { padding: "valid", dtype: "float64" });
    const b = new Conv2d(2, 3, 3, { padding: 0, dtype: "float64" });
    b.loadStateDict(a.stateDict());
    const x = f64(seq(2 * 2 * 5 * 5, 1, 0.3, 0.1), [2, 2, 5, 5]);
    expectClose(values(a.forward(x)), values(b.forward(x)), 1e-15);
  });

  it("dilation 1 and groups 1 give the same result as before", () => {
    setSeed(7);
    const conv = new Conv2d(2, 3, 3, { padding: 1, dtype: "float64" });
    const x = f64(seq(2 * 2 * 4 * 4, 1, 0.41, 0.7), [2, 2, 4, 4]);
    const w = conv.weight.tensor;
    const bias = (conv.bias as GradTensor).tensor;
    // Direct cross-correlation as the reference
    const xs = values(x);
    const ws = values(w);
    const bs = values(bias);
    const out = values(conv.forward(x));
    let o = 0;
    for (let n = 0; n < 2; n++) {
      for (let oc = 0; oc < 3; oc++) {
        for (let i = 0; i < 4; i++) {
          for (let j = 0; j < 4; j++) {
            let s = bs[oc] as number;
            for (let ic = 0; ic < 2; ic++) {
              for (let a = 0; a < 3; a++) {
                for (let b = 0; b < 3; b++) {
                  const ii = i + a - 1;
                  const jj = j + b - 1;
                  if (ii < 0 || jj < 0 || ii >= 4 || jj >= 4) continue;
                  s +=
                    (xs[((n * 2 + ic) * 4 + ii) * 4 + jj] as number) *
                    (ws[((oc * 2 + ic) * 3 + a) * 3 + b] as number);
                }
              }
            }
            expect(Math.abs((out[o++] as number) - s)).toBeLessThan(1e-12);
          }
        }
      }
    }
  });

  it("initializes the weights with the grouped fan-in", () => {
    setSeed(11);
    const conv = new Conv2d(8, 16, 3, { groups: 4, dtype: "float64" });
    expect(conv.weight.shape).toEqual([16, 2, 3, 3]);
    const bound = 1 / Math.sqrt(2 * 9);
    for (const v of values(conv.weight)) expect(Math.abs(v)).toBeLessThanOrEqual(bound);
    for (const v of values(conv.bias as GradTensor)) expect(Math.abs(v)).toBeLessThanOrEqual(bound);
    expect(new Conv1d(6, 6, 3, { groups: 6 }).weight.shape).toEqual([6, 1, 3]);
    expect(new Conv3d(4, 8, 3, { groups: 2 }).weight.shape).toEqual([8, 2, 3, 3, 3]);
  });

  it("validates dilation, groups and padding", () => {
    expect(() => new Conv1d(4, 4, 3, { dilation: 0 })).toThrow(InvalidParameterError);
    expect(() => new Conv1d(4, 4, 3, { dilation: 1.5 })).toThrow(InvalidParameterError);
    expect(() => new Conv2d(4, 4, 3, { dilation: [1, 0] })).toThrow(InvalidParameterError);
    expect(() => new Conv3d(4, 4, 3, { dilation: [1, 2] as never })).toThrow(InvalidParameterError);
    expect(() => new Conv1d(4, 4, 3, { groups: 0 })).toThrow(InvalidParameterError);
    expect(() => new Conv1d(4, 6, 3, { groups: 4 })).toThrow(InvalidParameterError);
    expect(() => new Conv2d(6, 4, 3, { groups: 4 })).toThrow(InvalidParameterError);
    expect(() => new Conv3d(5, 5, 3, { groups: 2 })).toThrow(InvalidParameterError);
    expect(() => new Conv1d(2, 2, 3, { padding: "same", stride: 2 })).toThrow(
      InvalidParameterError
    );
    expect(() => new Conv2d(2, 2, 3, { padding: "same", stride: [1, 2] })).toThrow(
      InvalidParameterError
    );
    expect(() => new Conv3d(2, 2, 3, { padding: "same", stride: 2 })).toThrow(
      InvalidParameterError
    );
    expect(() => new Conv1d(2, 2, 3, { padding: -1 })).toThrow(InvalidParameterError);
    expect(() => new Conv2d(2, 2, 3, { padding: "full" as "same" })).toThrow(InvalidParameterError);
  });

  it("reports a ShapeError when the dilated kernel does not fit", () => {
    // Effective kernel 5 on a length-4 input
    expect(() => new Conv1d(1, 1, 3, { dilation: 2 }).forward(zeros([1, 1, 4]))).toThrow(
      ShapeError
    );
    expect(() => new Conv2d(1, 1, 3, { dilation: 2 }).forward(zeros([1, 1, 4, 9]))).toThrow(
      ShapeError
    );
    expect(() => new Conv3d(1, 1, 3, { dilation: 2 }).forward(zeros([1, 1, 9, 9, 4]))).toThrow(
      ShapeError
    );
    // Padding makes it fit
    expect(
      new Conv1d(1, 1, 3, { dilation: 2, padding: 1 }).forward(zeros([1, 1, 4])).shape
    ).toEqual([1, 1, 2]);
  });

  it("checks channels against the layer, not the group", () => {
    const conv = new Conv2d(4, 4, 3, { groups: 2 });
    expect(() => conv.forward(zeros([1, 2, 5, 5]))).toThrow(ShapeError);
  });

  it("describes the new options in toString", () => {
    expect(new Conv1d(2, 4, 3, { dilation: 2, groups: 2, padding: "same" }).toString()).toBe(
      'Conv1d(2, 4, kernel_size=3, stride=1, padding="same", dilation=2, groups=2, bias=true)'
    );
    expect(new Conv2d(2, 2, 3).toString()).toBe(
      "Conv2d(2, 2, kernel_size=[3,3], stride=[1,1], padding=[0,0], bias=true)"
    );
    expect(new Conv2d(2, 2, 3, { padding: "valid", dilation: [2, 1] }).toString()).toContain(
      'padding="valid", dilation=[2,1]'
    );
    expect(new Conv3d(2, 2, 3, { groups: 2 }).toString()).toContain("groups=2");
  });

  it("trains a dilated grouped convolution by gradient descent", () => {
    setSeed(3);
    const conv = new Conv2d(2, 2, 3, { padding: "same", dilation: 2, groups: 2 });
    const x = tensor(seq(2 * 2 * 6 * 6, 1, 0.37, 0.2)).reshape([2, 2, 6, 6]);
    const target = tensor(seq(2 * 2 * 6 * 6, 0.5, 0.21, 1.2)).reshape([2, 2, 6, 6]);
    const optimizer = new SGD(conv.parameters(), { lr: 0.05 });
    let first = 0;
    let last = 0;
    for (let step = 0; step < 40; step++) {
      optimizer.zeroGrad();
      const loss = mseLoss(conv.forward(x), target) as GradTensor;
      if (step === 0) first = scalarOf(loss);
      last = scalarOf(loss);
      loss.backward();
      optimizer.step();
    }
    expect(last).toBeLessThan(first * 0.8);
  });

  it("float32 layers and plain tensors work, and noGrad returns a plain tensor", () => {
    setSeed(2);
    const conv = new Conv1d(2, 2, 3, { dilation: 2, padding: "same" });
    const x = tensor(seq(2 * 2 * 8, 1, 0.5, 0.1)).reshape([2, 2, 8]);
    const y = conv.forward(x);
    expect(GradTensor.isGradTensor(y)).toBe(true);
    expect(y.dtype).toBe("float32");
    const plain = noGrad(() => conv.forward(x));
    expect(GradTensor.isGradTensor(plain)).toBe(false);
    expectClose(values(plain), values(y), 1e-6);
    // Non-contiguous input
    const view = tensor(seq(2 * 8 * 2, 1, 0.5, 0.1))
      .reshape([2, 8, 2])
      .transpose([0, 2, 1]);
    expect(conv.forward(view).shape).toEqual([2, 2, 8]);
  });
});

// ---------------------------------------------------------------- pooling

describe("pooling ceilMode matches PyTorch", () => {
  const classes = { MaxPool1d, MaxPool2d, MaxPool3d, AvgPool1d, AvgPool2d, AvgPool3d };

  it.each(FIX.pool.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const layer = new classes[c.cls](c.args[0] as never, c.opts as never);
    const x = GradTensor.fromTensor(f64(seq(prod(c.xshape), 1.0, 0.83, 0.4), c.xshape), {
      requiresGrad: true,
    });
    const y = layer.forward(x);
    expect(y.shape).toEqual(c.yshape);
    expectClose(values(y), c.y);
    y.backward(f64(seq(prod(c.yshape), 1.0, 0.61, 0.9), c.yshape));
    expectClose(values(x.grad as Tensor), c.gx);
  });

  it("ceilMode is off by default and the output size follows the floor rule", () => {
    expect(new MaxPool1d(3, { stride: 2 }).forward(zeros([1, 1, 8])).shape).toEqual([1, 1, 3]);
    expect(new MaxPool1d(3, { stride: 2, ceilMode: true }).forward(zeros([1, 1, 8])).shape).toEqual(
      [1, 1, 4]
    );
    expect(new AvgPool2d(2, { ceilMode: false }).forward(zeros([1, 1, 5, 5])).shape).toEqual([
      1, 1, 2, 2,
    ]);
    expect(new AvgPool2d(2, { ceilMode: true }).forward(zeros([1, 1, 5, 5])).shape).toEqual([
      1, 1, 3, 3,
    ]);
  });

  it("partial windows average over the part that lies inside the padded input", () => {
    // [1, 2, 3, 4, 5], kernel 2, stride 2, ceil: windows [1,2], [3,4], [5] -> 1.5, 3.5, 5
    const x = f64([1, 2, 3, 4, 5], [1, 1, 5]);
    expect(values(new AvgPool1d(2, { ceilMode: true }).forward(x))).toEqual([1.5, 3.5, 5]);
    expect(values(new MaxPool1d(2, { ceilMode: true }).forward(x))).toEqual([2, 4, 5]);
  });

  it("works on views, integer input and 0 channels", () => {
    const base = f64(seq(2 * 6 * 5, 1, 0.7, 0.2), [2, 6, 5]);
    const view = base.transpose([0, 2, 1]);
    const copy = f64(values(view), [2, 5, 6]);
    for (const make of [
      () => new MaxPool1d(3, { stride: 2, ceilMode: true }),
      () => new AvgPool1d(3, { stride: 2, ceilMode: true }),
    ]) {
      expectClose(values(make().forward(view)), values(make().forward(copy)), 1e-15);
    }
    const ints = tensor([[[1, 5, 2, 8, 3]]], { dtype: "int32" });
    expect(values(new MaxPool1d(2, { ceilMode: true }).forward(ints))).toEqual([5, 8, 3]);
  });

  it("keeps toString unchanged unless ceilMode is on", () => {
    expect(new MaxPool2d(2).toString()).toBe(
      "MaxPool2d(kernel_size=[2,2], stride=[2,2], padding=[0,0])"
    );
    expect(new MaxPool2d(2, { ceilMode: true }).toString()).toContain("ceil_mode=true");
    expect(new AvgPool1d(2, { ceilMode: true }).toString()).toContain("ceil_mode=true");
    expect(new MaxPool3d(2, { ceilMode: true }).toString()).toContain("ceil_mode=true");
  });
});

// ---------------------------------------------------------------- attention

describe("MultiheadAttention needWeights and keyPaddingMask match PyTorch", () => {
  const E = 4;
  const B = 2;
  const L = 3;
  const S = 4;
  const q = f64(seq(B * L * E, 1.0, 0.9, 0.1), [B, L, E]);
  const k = f64(seq(B * S * E, 1.0, 0.7, 0.6), [B, S, E]);
  const v = f64(seq(B * S * E, 1.0, 0.45, 1.3), [B, S, E]);
  const kpmBool = tensor(
    FIX.mha.kpmBool.map((b) => b !== 0),
    { dtype: "bool" }
  ).reshape([B, S]);
  const kpmFloat = f64(FIX.mha.kpmFloat, [B, S]);
  const attnBool = tensor(
    FIX.mha.attnBool.map((b) => b !== 0),
    { dtype: "bool" }
  ).reshape([L, S]);

  function makeMha(): MultiheadAttention {
    const mha = new MultiheadAttention(E, 2, { dtype: "float64" });
    mha.loadStateDict(paramState(FIX.mha.keys, 0.5));
    return mha;
  }

  it.each(FIX.mha.cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    const mha = makeMha();
    const unbatched = c.qshape.length === 2;
    const qq = unbatched ? f64(seq(L * E, 1.0, 0.9, 0.1), [L, E]) : q;
    const kk = unbatched ? f64(seq(S * E, 1.0, 0.7, 0.6), [S, E]) : k;
    const vv = c.opts.valueIsKey ? kk : v;
    let kpm: Tensor | undefined;
    if (c.opts.kpm === "bool") {
      kpm = unbatched
        ? tensor(
            FIX.mha.kpmBool.slice(0, S).map((b) => b !== 0),
            { dtype: "bool" }
          )
        : kpmBool;
    } else if (c.opts.kpm === "float") {
      kpm = kpmFloat;
    }
    const options = {
      needWeights: true as const,
      ...(c.opts.averageAttnWeights === undefined
        ? {}
        : { averageAttnWeights: c.opts.averageAttnWeights }),
      ...(kpm === undefined ? {} : { keyPaddingMask: kpm }),
    };
    const [out, weights] = mha.forward(
      qq,
      kk,
      vv,
      c.opts.attn === "bool" ? attnBool : undefined,
      options
    );
    expect(weights.shape).toEqual(c.wshape);
    expect(out.shape).toEqual(qq.shape);
    expectClose(values(out), c.out);
    expectClose(values(weights), c.w);
  });

  it("returns only the output when needWeights is off or absent", () => {
    const mha = makeMha();
    const plain = mha.forward(q, k, v);
    expect(Array.isArray(plain)).toBe(false);
    const off = mha.forward(q, k, v, undefined, { needWeights: false });
    expect(Array.isArray(off)).toBe(false);
    expectClose(values(off as Tensor), values(plain as Tensor), 1e-15);
    const withMaskOnly = mha.forward(q, k, v, undefined, { keyPaddingMask: kpmBool });
    expect(Array.isArray(withMaskOnly)).toBe(false);
    expect((withMaskOnly as Tensor).shape).toEqual([B, L, E]);
  });

  it("accepts the options in place of the trailing tensors", () => {
    const mha = makeMha();
    const [o1, w1] = mha.forward(q, { needWeights: true });
    const [o2, w2] = mha.forward(q, q, q, undefined, { needWeights: true });
    expectClose(values(o1), values(o2), 1e-15);
    expectClose(values(w1), values(w2), 1e-15);
    const [o3] = mha.forward(q, k, v, { needWeights: true, keyPaddingMask: kpmBool });
    const [o4] = mha.forward(q, k, v, undefined, { needWeights: true, keyPaddingMask: kpmBool });
    expectClose(values(o3), values(o4), 1e-15);
  });

  it("returns GradTensors for GradTensor input and backpropagates through the weights", () => {
    const mha = makeMha();
    const x = GradTensor.fromTensor(q, { requiresGrad: true });
    const [out, weights] = mha.forward(x, undefined, undefined, undefined, {
      needWeights: true,
      averageAttnWeights: false,
    });
    expect(GradTensor.isGradTensor(out)).toBe(true);
    expect(GradTensor.isGradTensor(weights)).toBe(true);
    expect(weights.shape).toEqual([B, 2, L, L]);
    // Every attention row is a distribution
    const rows = values(weights);
    for (let i = 0; i < rows.length; i += L) {
      expect(rows.slice(i, i + L).reduce((a, b) => a + b, 0)).toBeCloseTo(1, 12);
    }
    weights.backward(f64(seq(weights.size, 1, 0.3, 0.2), weights.shape as number[]));
    // The weights depend on the query and key projections only
    expect(x.grad).not.toBeNull();
    const named = new Map(mha.namedParameters());
    expect(named.get("in_proj_weight_q")?.grad).not.toBeNull();
    expect(named.get("in_proj_weight_k")?.grad).not.toBeNull();
    for (const p of mha.parameters()) p.zeroGrad();
    out.backward(f64(seq(out.size, 1, 0.3, 0.2), out.shape as number[]));
    for (const p of mha.parameters()) expect(p.grad).not.toBeNull();
  });

  it("plain tensors give plain tensors inside noGrad and tracked tensors otherwise", () => {
    const mha = makeMha();
    const [o, w] = mha.forward(q, undefined, undefined, undefined, { needWeights: true });
    expect(GradTensor.isGradTensor(o)).toBe(true);
    expect(GradTensor.isGradTensor(w)).toBe(true);
    const [o2, w2] = noGrad(() =>
      mha.forward(q, undefined, undefined, undefined, { needWeights: true })
    );
    expect(GradTensor.isGradTensor(o2)).toBe(false);
    expect(GradTensor.isGradTensor(w2)).toBe(false);
  });

  it("masked key positions get zero weight", () => {
    const mha = makeMha();
    const [, w] = mha.forward(q, k, v, undefined, {
      needWeights: true,
      keyPaddingMask: kpmBool,
    });
    const flat = values(w);
    // batch 0 masks key 3; batch 1 masks keys 1, 2 and 3
    for (let i = 0; i < L; i++) {
      expect(flat[i * S + 3]).toBe(0);
      expect(flat[L * S + i * S + 1]).toBe(0);
      expect(flat[L * S + i * S + 2]).toBe(0);
      expect(flat[L * S + i * S + 3]).toBe(0);
      expect(flat[L * S + i * S]).toBeCloseTo(1, 12);
    }
  });

  it("applies attention dropout to the returned weights in training mode", () => {
    setSeed(4);
    const mha = new MultiheadAttention(E, 2, { dtype: "float64", dropout: 0.5 });
    const [, trainWeights] = mha.forward(q, undefined, undefined, undefined, {
      needWeights: true,
    });
    expect(values(trainWeights).some((x) => x === 0)).toBe(true);
    mha.eval();
    const [, evalWeights] = mha.forward(q, undefined, undefined, undefined, {
      needWeights: true,
    });
    expect(values(evalWeights).every((x) => x > 0)).toBe(true);
  });

  it("validates keyPaddingMask", () => {
    const mha = makeMha();
    const bad = tensor([true, false, false], { dtype: "bool" });
    expect(() => mha.forward(q, k, v, undefined, { keyPaddingMask: bad })).toThrow(ShapeError);
    const wrongBatch = tensor([[true, false, false, false]], { dtype: "bool" });
    expect(() => mha.forward(q, k, v, undefined, { keyPaddingMask: wrongBatch })).toThrow(
      ShapeError
    );
    const text = tensor(["a", "b"]);
    expect(() => mha.forward(q, k, v, undefined, { keyPaddingMask: text })).toThrow(DTypeError);
    // A key length that differs from the query length uses the key length
    const ok = mha.forward(q, k, v, undefined, { keyPaddingMask: kpmBool });
    expect((ok as Tensor).shape).toEqual([B, L, E]);
  });

  it("keeps the float32 parameter dtype for the output and the weights", () => {
    const mha = new MultiheadAttention(E, 2);
    const x = tensor(seq(B * L * E, 1, 0.9, 0.1)).reshape([B, L, E]);
    const [out, w] = mha.forward(x, undefined, undefined, undefined, { needWeights: true });
    expect(out.dtype).toBe("float32");
    expect(w.dtype).toBe("float32");
  });
});

// ---------------------------------------------------------------- transformer layers

describe("Transformer layers: activation and normFirst match PyTorch", () => {
  const E = 4;
  const B = 2;
  const L = 3;
  const S = 4;
  const x = f64(seq(B * L * E, 1.0, 0.8, 0.2), [B, L, E]);
  const mem = f64(seq(B * S * E, 1.0, 0.5, 0.9), [B, S, E]);
  const causal = f64(FIX.trans.causal, [L, L]);

  function makeLayer(c: TransCase): TransformerEncoderLayer | TransformerDecoderLayer {
    const options = { dropout: 0, dtype: "float64" as const, activation: c.act, normFirst: c.nf };
    const layer =
      c.kind === "enc"
        ? new TransformerEncoderLayer(E, 2, 6, options)
        : new TransformerDecoderLayer(E, 2, 6, options);
    layer.loadStateDict(paramState(c.kind === "enc" ? FIX.trans.encKeys : FIX.trans.decKeys, 0.4));
    return layer;
  }

  function run(layer: TransformerEncoderLayer | TransformerDecoderLayer, c: TransCase): Tensor {
    const out =
      layer instanceof TransformerEncoderLayer
        ? layer.forward(x, causal)
        : layer.forward(x, mem, causal);
    expect(c.shape).toEqual(out.shape);
    return raw(out);
  }

  it.each(FIX.trans.cases.map((c) => [c.name, c] as const))("%s", (_name, c) => {
    expectClose(values(run(makeLayer(c), c)), c.out);
  });

  it("clone keeps activation and normFirst", () => {
    const c = FIX.trans.cases.find((t) => t.kind === "enc" && t.act === "gelu" && t.nf);
    const d = FIX.trans.cases.find((t) => t.kind === "dec" && t.act === "gelu" && t.nf);
    if (!c || !d) throw new Error("fixture missing");
    const enc = makeLayer(c) as TransformerEncoderLayer;
    expectClose(values(run(enc.clone(), c)), c.out);
    const dec = makeLayer(d) as TransformerDecoderLayer;
    expectClose(values(run(dec.clone(), d)), d.out);
  });

  it("TransformerEncoder and TransformerDecoder stack layers that keep the options", () => {
    const layer = new TransformerEncoderLayer(E, 2, 6, {
      dropout: 0,
      activation: "gelu",
      normFirst: true,
      dtype: "float64",
    });
    const encoder = new TransformerEncoder(layer, 2, {
      norm: new LayerNorm(E, { dtype: "float64" }),
    });
    expect(encoder.forward(x).shape).toEqual([B, L, E]);
    expect(encoder.toString()).toContain("num_layers=2");
    const decoderLayer = new TransformerDecoderLayer(E, 2, 6, {
      dropout: 0,
      activation: "gelu",
      normFirst: true,
      dtype: "float64",
    });
    const decoder = new TransformerDecoder(decoderLayer, 2);
    expect(decoder.forward(x, mem).shape).toEqual([B, L, E]);
    // The second layer is a clone with the same options: same architecture, new weights loaded
    expect(layer.toString()).toContain("activation=gelu");
    expect(layer.toString()).toContain("norm_first=true");
  });

  it("FullTransformer passes activation and normFirst to its layers", () => {
    setSeed(8);
    const model = new FullTransformer(E, 2, 1, 1, 6, {
      dropout: 0,
      activation: "gelu",
      normFirst: true,
      finalNorm: true,
    });
    const out = model.forward(
      tensor(seq(B * S * E, 1, 0.4, 0.2)).reshape([B, S, E]),
      tensor(seq(B * L * E, 1, 0.3, 0.6)).reshape([B, L, E])
    );
    expect(raw(out).shape).toEqual([B, L, E]);
    const relu = new FullTransformer(E, 2, 1, 1, 6, { dropout: 0 });
    expect(relu.toString()).toContain("TransformerEncoder");
  });

  it("accepts the options in every constructor form", () => {
    const c = FIX.trans.cases.find((t) => t.kind === "enc" && t.act === "gelu" && t.nf);
    if (!c) throw new Error("fixture missing");
    const forms: TransformerEncoderLayer[] = [
      new TransformerEncoderLayer({
        dModel: E,
        nHead: 2,
        dimFeedforward: 6,
        dropout: 0,
        dtype: "float64",
        activation: "gelu",
        normFirst: true,
      }),
      new TransformerEncoderLayer(E, 2, {
        dFF: 6,
        dropout: 0,
        dtype: "float64",
        activation: "gelu",
        normFirst: true,
      }),
    ];
    for (const layer of forms) {
      layer.loadStateDict(paramState(FIX.trans.encKeys, 0.4));
      expectClose(values(layer.forward(x, causal)), c.out);
    }
  });

  it("rejects an unknown activation", () => {
    expect(() => new TransformerEncoderLayer(E, 2, 6, { activation: "tanh" as "relu" })).toThrow(
      InvalidParameterError
    );
    expect(() => new TransformerDecoderLayer(E, 2, 6, { activation: "silu" as "relu" })).toThrow(
      InvalidParameterError
    );
  });

  it("defaults stay post-norm with ReLU and the new layers train", () => {
    setSeed(13);
    const layer = new TransformerEncoderLayer(E, 2, 6, { dropout: 0 });
    expect(layer.toString()).toContain("activation=relu, norm_first=false");
    const pre = new TransformerEncoderLayer(E, 2, 6, {
      dropout: 0,
      activation: "gelu",
      normFirst: true,
    });
    const out = pre.forward(tensor(seq(B * L * E, 1, 0.8, 0.2)).reshape([B, L, E]));
    const loss = mseLoss(out, zeros([B, L, E])) as GradTensor;
    loss.backward();
    for (const p of pre.parameters()) expect(p.grad).not.toBeNull();
  });
});

// ---------------------------------------------------------------- trainer

describe("Trainer accumulationSteps and restoreBestWeights", () => {
  function makeData(nBatches: number): Array<[Tensor, Tensor]> {
    return Array.from({ length: nBatches }, (_, i) => [
      f64(seq(6, 1.0, 0.9, 0.3 * i), [3, 2]),
      f64(seq(3, 1.0, 0.6, 0.7 * i), [3, 1]),
    ]);
  }

  function makeModel(): Linear {
    const model = new Linear(2, 1, { dtype: "float64" });
    model.loadStateDict({
      parameters: {
        weight: { data: [0.5, -0.3], shape: [1, 2], dtype: "float64" },
        bias: { data: [0.1], shape: [1], dtype: "float64" },
      },
    });
    return model;
  }

  function weightsOf(model: Linear): number[] {
    return [...values(paramOf(model, "weight")), ...values(paramOf(model, "bias"))];
  }

  const lossFn = (out: AnyTensor, y: Tensor): AnyTensor => mseLoss(out as Tensor, y);

  function counting(optimizer: SGD): {
    step(): void;
    zeroGrad(): void;
    steps: number;
    zeros: number;
  } {
    const wrapper = {
      steps: 0,
      zeros: 0,
      step(): void {
        wrapper.steps++;
        optimizer.step();
      },
      zeroGrad(): void {
        wrapper.zeros++;
        optimizer.zeroGrad();
      },
    };
    return wrapper;
  }

  it.each([
    ["four batches in groups of two", 4, 2, "four_two"],
    ["a trailing partial group", 3, 2, "three_two"],
    ["no accumulation", 3, 1, "three_one"],
    ["a trailing group of two out of three", 5, 3, "five_three"],
  ] as const)("matches the PyTorch loop: %s", (_name, batches, accum, key) => {
    const model = makeModel();
    const trainer = new Trainer(model, new SGD(model.parameters(), { lr: 0.1 }), lossFn, {
      epochs: 1,
      accumulationSteps: accum,
    });
    trainer.fit(makeData(batches));
    expectClose(weightsOf(model), FIX.train[key], 1e-9);
  });

  it("steps once per group and resets the group at every epoch", () => {
    const model = makeModel();
    const optimizer = counting(new SGD(model.parameters(), { lr: 0.1 }));
    const trainer = new Trainer(model, optimizer, lossFn, { epochs: 2, accumulationSteps: 3 });
    trainer.fit(makeData(5));
    // 5 batches: one full group of 3 and a partial group of 2, in each of the 2 epochs
    expect(optimizer.steps).toBe(4);
    // Gradients are cleared at the start of each group
    expect(optimizer.zeros).toBe(4);
  });

  it("an accumulation of N equal batches equals one batch of the combined samples", () => {
    const xs = [f64(seq(6, 1, 0.5, 0.1), [3, 2]), f64(seq(6, 1, 0.5, 2.1), [3, 2])];
    const ys = [f64(seq(3, 1, 0.8, 0.4), [3, 1]), f64(seq(3, 1, 0.8, 1.4), [3, 1])];
    const joined: [Tensor, Tensor] = [
      f64([...values(xs[0] as Tensor), ...values(xs[1] as Tensor)], [6, 2]),
      f64([...values(ys[0] as Tensor), ...values(ys[1] as Tensor)], [6, 1]),
    ];
    const a = makeModel();
    new Trainer(a, new SGD(a.parameters(), { lr: 0.2 }), lossFn, {
      epochs: 5,
      accumulationSteps: 2,
    }).fit([
      [xs[0] as Tensor, ys[0] as Tensor],
      [xs[1] as Tensor, ys[1] as Tensor],
    ]);
    const b = makeModel();
    new Trainer(b, new SGD(b.parameters(), { lr: 0.2 }), lossFn, { epochs: 5 }).fit([joined]);
    expectClose(weightsOf(a), weightsOf(b), 1e-12);
  });

  it("reports the unscaled batch loss and clips the accumulated gradient once per step", () => {
    const data = makeData(2);
    const plainModel = makeModel();
    const plain = new Trainer(plainModel, new SGD(plainModel.parameters(), { lr: 0.1 }), lossFn, {
      epochs: 1,
    }).fit(data);
    const accModel = makeModel();
    const acc = new Trainer(accModel, new SGD(accModel.parameters(), { lr: 0.1 }), lossFn, {
      epochs: 1,
      accumulationSteps: 2,
      maxGradNorm: 1e-3,
    }).fit(data);
    // The first batch is evaluated before any update in both runs, so the means differ only
    // through the second batch; both report plain (unscaled) losses of the same magnitude.
    expect(acc.history[0]?.trainLoss).toBeGreaterThan(0);
    expect(
      Math.abs((acc.history[0]?.trainLoss ?? 0) - (plain.history[0]?.trainLoss ?? 0))
    ).toBeLessThan(0.5);
    // One clipped step of norm at most lr * maxGradNorm
    const start = weightsOf(makeModel());
    const end = weightsOf(accModel);
    const moved = Math.hypot(...end.map((v, i) => v - (start[i] as number)));
    expect(moved).toBeCloseTo(0.1 * 1e-3, 9);
  });

  it("works with fitAsync and with a plain-tensor loss", async () => {
    const model = makeModel();
    const trainer = new Trainer(model, new SGD(model.parameters(), { lr: 0.1 }), lossFn, {
      epochs: 1,
      accumulationSteps: 2,
    });
    await trainer.fitAsync(makeData(4));
    expectClose(weightsOf(model), FIX.train.four_two, 1e-9);

    const frozen = makeModel();
    const optimizer = counting(new SGD(frozen.parameters(), { lr: 0.1 }));
    const noLoss = new Trainer(frozen, optimizer, (out, y) => noGrad(() => mseLoss(raw(out), y)), {
      epochs: 1,
      accumulationSteps: 2,
    });
    noLoss.fit(makeData(4));
    expect(optimizer.steps).toBe(2);
  });

  it("rejects an invalid accumulationSteps", () => {
    const model = makeModel();
    const optimizer = new SGD(model.parameters(), { lr: 0.1 });
    for (const bad of [0, -1, 1.5, Number.NaN]) {
      expect(() => new Trainer(model, optimizer, lossFn, { accumulationSteps: bad })).toThrow(
        InvalidParameterError
      );
    }
  });

  describe("restoreBestWeights", () => {
    /** Optimizer that sets the single weight to a scheduled value after every step. */
    function scheduled(model: Linear, schedule: number[]): TrainerOptimizerLike {
      let epoch = 0;
      return {
        step(): void {
          const next = schedule[Math.min(epoch, schedule.length - 1)] as number;
          epoch++;
          model.loadStateDict({
            parameters: { weight: { data: [next], shape: [1, 1], dtype: "float64" } },
          });
        },
        zeroGrad(): void {},
      };
    }
    type TrainerOptimizerLike = { step(): void; zeroGrad(): void };

    const x = f64([1, 2], [2, 1]);
    const y = f64([3, 6], [2, 1]);

    function setup(initial: number): Linear {
      const model = new Linear(1, 1, { bias: false, dtype: "float64" });
      model.loadStateDict({
        parameters: { weight: { data: [initial], shape: [1, 1], dtype: "float64" } },
      });
      return model;
    }

    it("restores the weights of the best validation epoch", () => {
      const model = setup(1);
      // Validation loss after each epoch: w = 1, 2.9, 5, 7 -> epoch 2 is the best
      const trainer = new Trainer(model, scheduled(model, [1, 2.9, 5, 7]), lossFn, {
        epochs: 4,
        restoreBestWeights: true,
      });
      const result = trainer.fit([[x, y]], [[x, y]]);
      expect(result.history).toHaveLength(4);
      expect(result.bestEpoch).toBe(2);
      expect(scalarOf(paramOf(model, "weight"))).toBeCloseTo(2.9, 12);
    });

    it("leaves the final weights alone when the option is off", () => {
      const model = setup(1);
      const trainer = new Trainer(model, scheduled(model, [1, 2.9, 5, 7]), lossFn, { epochs: 4 });
      const result = trainer.fit([[x, y]], [[x, y]]);
      expect(scalarOf(paramOf(model, "weight"))).toBe(7);
      expect(result.bestEpoch).toBeUndefined();
    });

    it("restores after early stopping", () => {
      const model = setup(1);
      const trainer = new Trainer(model, scheduled(model, [1, 2.9, 5, 7, 9]), lossFn, {
        epochs: 10,
        earlyStopping: { patience: 2 },
        restoreBestWeights: true,
      });
      const result = trainer.fit([[x, y]], [[x, y]]);
      expect(result.stoppedEarly).toBe(true);
      expect(result.history).toHaveLength(4);
      expect(result.bestEpoch).toBe(2);
      expect(scalarOf(paramOf(model, "weight"))).toBeCloseTo(2.9, 12);
    });

    it("uses the training loss without validation data and keeps the end-of-epoch weights", () => {
      const model = setup(1);
      // Training losses use the weights before each update: 1, 2.9, 5, 7 -> epoch 2 is the
      // best, and the weights at the end of epoch 2 are the scheduled value 5.
      const trainer = new Trainer(model, scheduled(model, [2.9, 5, 7, 9]), lossFn, {
        epochs: 4,
        restoreBestWeights: true,
      });
      const result = trainer.fit([[x, y]]);
      expect(result.bestEpoch).toBe(2);
      expect(scalarOf(paramOf(model, "weight"))).toBe(5);
    });

    it("keeps the weights when every loss is NaN and works with fitAsync", async () => {
      const model = setup(1);
      const nanLoss = (): AnyTensor => tensor([Number.NaN]);
      const trainer = new Trainer(model, scheduled(model, [4, 5]), nanLoss, {
        epochs: 2,
        restoreBestWeights: true,
      });
      const result = await trainer.fitAsync([[x, y]], [[x, y]]);
      expect(result.bestEpoch).toBeUndefined();
      expect(scalarOf(paramOf(model, "weight"))).toBe(5);

      const model2 = setup(1);
      const trainer2 = new Trainer(model2, scheduled(model2, [1, 2.9, 5, 7]), lossFn, {
        epochs: 4,
        restoreBestWeights: true,
      });
      const result2 = await trainer2.fitAsync([[x, y]], [[x, y]]);
      expect(result2.bestEpoch).toBe(2);
      expect(scalarOf(paramOf(model2, "weight"))).toBeCloseTo(2.9, 12);
    });

    it("starts again on every fit", () => {
      const model = setup(1);
      const trainer = new Trainer(model, scheduled(model, [1, 2.9, 5, 7, 7, 7, 7, 7]), lossFn, {
        epochs: 2,
        restoreBestWeights: true,
      });
      trainer.fit([[x, y]], [[x, y]]);
      expect(scalarOf(paramOf(model, "weight"))).toBeCloseTo(2.9, 12);
      // Second fit: epochs see 5 and 7, so the best of this run is its first epoch (w = 5)
      const second = trainer.fit([[x, y]], [[x, y]]);
      expect(second.bestEpoch).toBe(1);
      expect(scalarOf(paramOf(model, "weight"))).toBe(5);
    });
  });
});

// ---------------------------------------------------------------- optimizers

describe("optimizers skip parameters whose grad is null", () => {
  const initialA = [1, -2, 0.5];
  const initialB = [3, 4];

  const makers: Array<[string, (params: GradTensor[]) => { step(): number | undefined }]> = [
    ["SGD", (p) => new SGD(p, { lr: 0.1, momentum: 0.9 })],
    ["Adam", (p) => new Adam(p, { lr: 0.05 })],
    ["AdamW", (p) => new AdamW(p, { lr: 0.05, weightDecay: 0.1 })],
    ["RMSprop", (p) => new RMSprop(p, { lr: 0.05 })],
    ["Adagrad", (p) => new Adagrad(p, { lr: 0.1 })],
    ["AdaDelta", (p) => new AdaDelta(p, { lr: 1 })],
    ["Adamax", (p) => new Adamax(p, { lr: 0.05 })],
    ["Nadam", (p) => new Nadam(p, { lr: 0.05 })],
    ["RAdam", (p) => new RAdam(p, { lr: 0.05 })],
    ["ASGD", (p) => new ASGD(p, { lr: 0.05 })],
    ["Rprop", (p) => new Rprop(p, { lr: 0.05 })],
    ["Lion", (p) => new Lion(p, { lr: 0.05 })],
    ["LAMB", (p) => new LAMB(p, { lr: 0.05 })],
    ["LARS", (p) => new LARS(p, { lr: 0.05 })],
    ["SparseAdam", (p) => new SparseAdam(p, { lr: 0.05 })],
  ];

  function makeParams(): { a: GradTensor; b: GradTensor } {
    return {
      a: parameter(f64(initialA, [3])),
      b: parameter(f64(initialB, [2])),
    };
  }

  it.each(makers)("%s leaves a parameter without a gradient untouched", (_name, make) => {
    const { a, b } = makeParams();
    const optimizer = make([a, b]);
    for (let s = 0; s < 3; s++) {
      a.setGrad(
        f64(
          [0.3, -0.2, 0.1].map((g) => g * (s + 1)),
          [3]
        )
      );
      expect(() => optimizer.step()).not.toThrow();
    }
    expect(values(b)).toEqual(initialB);
    expect(b.grad).toBeNull();
    const moved = values(a);
    expect(moved.some((v, i) => v !== initialA[i])).toBe(true);
  });

  it.each(makers)("%s does nothing when no parameter has a gradient", (_name, make) => {
    const { a, b } = makeParams();
    const optimizer = make([a, b]);
    expect(() => optimizer.step()).not.toThrow();
    expect(values(a)).toEqual(initialA);
    expect(values(b)).toEqual(initialB);
  });

  it.each([
    "sgd",
    "adam",
    "adamw",
    "rmsprop",
    "adagrad",
  ] as const)("%s matches PyTorch when the other parameter has no gradient", (name) => {
    const { a, b } = makeParams();
    const make = makers.find(([n]) => n.toLowerCase() === name)?.[1];
    if (!make) throw new Error("missing optimizer");
    const optimizer = make([a, b]);
    for (let s = 0; s < 3; s++) {
      a.setGrad(
        f64(
          [0.3, -0.2, 0.1].map((g) => g * (s + 1)),
          [3]
        )
      );
      optimizer.step();
    }
    const expected = FIX.optim[name] as { a: number[]; b: number[] };
    expectClose(values(a), expected.a, 1e-8);
    expectClose(values(b), expected.b, 1e-12);
  });

  it("a parameter that gets its first gradient later starts with fresh optimizer state", () => {
    const { a, b } = makeParams();
    const optimizer = new Adam([a, b], { lr: 0.05 });
    a.setGrad(f64([0.3, -0.2, 0.1], [3]));
    optimizer.step();
    expect(values(b)).toEqual(initialB);
    a.setGrad(f64([0.3, -0.2, 0.1], [3]));
    b.setGrad(f64([2, -4], [2]));
    optimizer.step();
    // First Adam step of b: lr * g / (|g| + eps) in magnitude, in the direction of -g
    expectClose(values(b), [3 - 0.05, 4 + 0.05], 1e-6);
  });

  it("frozen parameters and parameters without gradient can be mixed", () => {
    const a = parameter(f64([1, 2], [2]));
    const frozen = parameter(f64([5, 6], [2]));
    const unused = parameter(f64([7, 8], [2]));
    frozen.setGrad(f64([1, 1], [2]));
    frozen.setRequiresGrad(false);
    a.setGrad(f64([1, 1], [2]));
    const optimizer = new SGD([a, frozen, unused], { lr: 0.5 });
    optimizer.step();
    expect(values(a)).toEqual([0.5, 1.5]);
    expect(values(frozen)).toEqual([5, 6]);
    expect(values(unused)).toEqual([7, 8]);
  });

  it("zeroGrad still gives a zero gradient, which is a real (zero) update", () => {
    const a = parameter(f64([1, 2], [2]));
    const optimizer = new SGD([a], { lr: 0.5, weightDecay: 0.1 });
    optimizer.zeroGrad();
    optimizer.step();
    // Zero gradient plus weight decay moves the parameter
    expectClose(values(a), [0.95, 1.9], 1e-12);
  });

  it("LBFGS treats a parameter without a gradient as a zero gradient", () => {
    const a = parameter(f64([4, -3], [2]));
    const b = parameter(f64([9, 9, 9], [3]));
    const optimizer = new LBFGS([a, b], { lr: 1, maxIter: 20 });
    const target = [1, 2];
    const loss = (): number => {
      const av = values(a);
      const diff = av.map((v, i) => v - (target[i] as number));
      a.setGrad(
        f64(
          diff.map((d) => 2 * d),
          [2]
        )
      );
      return diff.reduce((s, d) => s + d * d, 0);
    };
    for (let i = 0; i < 3; i++) optimizer.step(loss);
    expectClose(values(a), target, 1e-6);
    expect(values(b)).toEqual([9, 9, 9]);
  });

  it("counts every step call, also when nothing was updated", () => {
    const { a } = makeParams();
    const optimizer = new SGD([a], { lr: 0.1 });
    optimizer.step();
    optimizer.step();
    expect(optimizer.stepCount).toBe(2);
  });
});
